mapper.select:
SELECT FROM trips t WHERE t.id IN
#{id,javaType=java.util.UUID,jdbcType=OTHER}
AND t.visibility = 'PUBLIC' AND t.is_deleted = FALSE AND NOT EXISTS ( SELECT 1 FROM content_takedowns ct WHERE ct.content_type = 'TRIP' AND ct.content_id = t.id AND ct.restored_at IS NULL)

SELECT t.id, t.name, t.cover_image_url, t.destination, t.destination_place_id, t.destination_lat, t.destination_lng, t.start_date, t.end_date, t.budget, t.currency, t.status, t.visibility, t.share_code, t.share_expenses, t.share_notes, t.description, t.timezone, t.owner_id, t.starting_point_name, t.starting_point_address, t.starting_point_lat, t.starting_point_lng, t.starting_point_time, t.view_count, t.copy_count, t.helpful_votes, t.unhelpful_votes, t.is_deleted, t.deleted_at, t.public_shared_at, t.created_at, t.updated_at, t.location_image_id,
CASE WHEN t.destination_lat IS NULL OR t.destination_lng IS NULL THEN NULL WHEN EXISTS ( SELECT 1 FROM provinces fp WHERE fp.geom IS NOT NULL AND ST_Covers(fp.geom, ST_SetSRID(ST_MakePoint(#{focusLng}::float8, #{focusLat}::float8), 4326)) AND ST_Covers(fp.geom, ST_SetSRID(ST_MakePoint(t.destination_lng::float8, t.destination_lat::float8), 4326))) THEN 0 ELSE 1 + FLOOR(ST_Distance( goroute_point(t.destination_lat::float8, t.destination_lng::float8), goroute_point(#{focusLat}::float8, #{focusLng}::float8)) / 100000)::int END
NULL::int AS focus_rank FROM trips t JOIN user_follows f ON f.following_id = t.owner_id AND f.follower_id = #{viewerId,javaType=java.util.UUID,jdbcType=OTHER} JOIN users u ON u.id = t.owner_id AND u.deleted_at IS NULL WHERE t.visibility = 'PUBLIC' AND t.is_deleted = FALSE AND NOT EXISTS ( SELECT 1 FROM user_blocks b WHERE (b.blocker_id = #{viewerId,javaType=java.util.UUID,jdbcType=OTHER} AND b.blocked_id = t.owner_id) OR (b.blocker_id = t.owner_id AND b.blocked_id = #{viewerId,javaType=java.util.UUID,jdbcType=OTHER})) AND NOT EXISTS ( SELECT 1 FROM content_takedowns ct WHERE ct.content_type = 'TRIP' AND ct.content_id = t.id AND ct.restored_at IS NULL) ORDER BY focus_rank ASC NULLS LAST, COALESCE(t.public_shared_at, t.created_at) DESC, t.id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE trips
SET activity_count = (SELECT COUNT(*) FROM activities a WHERE a.trip_id = trips.id)
WHERE id = #{tripId,javaType=java.util.UUID,jdbcType=OTHER}
